lee: opened a PR to modernize SDK snippets: async TS streaming + clearer Go pagination example. https://github.com/redwood-inference/docs/pull/889
sarah: nice. what are the concrete changes?
lee: main goals: 1) show async iterator pattern in TS (await for await), 2) show graceful retry with jitter, 3) add an explicit check for cursor == null before calling next page so folks don't hit the support case we saw.
max: can you paste the TS snippet here so i can sanity-check syntax quickly?
lee: sure:
```ts
// typescript async streaming w/ simple retry + async iterator
import { Redwood } from "@redwood/inference"

async function streamExample() {
  const client = new Redwood()
  let attempts = 0
  const maxAttempts = 4
  while (attempts < maxAttempts) {
    try {
      const stream = await client.stream("gpt-open-1", { prompt: "Hello" })
      for await (const chunk of stream) {
        process.stdout.write(chunk.text)
      }
      return
    } catch (err) {
      const backoff = (Math.random() + 1) * Math.pow(2, attempts) * 100
      await new Promise(r => setTimeout(r, backoff))
      attempts++
      if (attempts === maxAttempts) throw err
    }
  }
}
```
jamie: looks good. the TS pattern should be easy for users. do we also need a small Go snippet for pagination null cursor handling?
lee: yes, that was the ask from support. here's a compact Go example:
```go
// go pagination + nil cursor guard + retry (backoff with jitter)
package examples

import (
  "context"
  "errors"
  "math/rand"
  "time"
  "github.com/redwood-inference/sdk"
)

func FetchAll(ctx context.Context, client *sdk.Client) ([]string, error) {
  var results []string
  var cursor *string = nil
  for {
    resp, err := client.ListItems(ctx, &sdk.ListParams{Cursor: cursor})
    if err != nil {
      // simple retry with jitter
      ok := retryWithJitter(ctx, func() error { _, err = client.ListItems(ctx, &sdk.ListParams{Cursor: cursor}); return err })
      if !ok { return nil, errors.New("failed after retries") }
    }

    // guard: resp.Cursor may be nil -> stop pagination
    results = append(results, resp.Items...)
    if resp.Cursor == nil || len(resp.Items) == 0 {
      break
    }
    cursor = resp.Cursor
  }
  return results, nil
}

func retryWithJitter(ctx context.Context, fn func() error) bool {
  backoff := 100 * time.Millisecond
  for i := 0; i < 3; i++ {
    if err := fn(); err == nil {
      return true
    }
    jitter := time.Duration(rand.Intn(100)) * time.Millisecond
    select {
    case <-ctx.Done(): return false
    case <-time.After(backoff + jitter): backoff *= 2
    }
  }
  return false
}
```
